import{_ as s,c as a,o as e,ag as i}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Award Bullet AI Prompt Template","description":"","frontmatter":{"title":"Award Bullet AI Prompt Template"},"headers":[],"relativePath":"ai-ml/award-bullet-ai-prompt-template.md","filePath":"ai-ml/award-bullet-ai-prompt-template.md","lastUpdated":null}'),p={name:"ai-ml/award-bullet-ai-prompt-template.md"};function l(t,n,r,o,c,u){return e(),a("div",null,[...n[0]||(n[0]=[i(`<h1 id="award-bullet-ai-prompt-template" tabindex="-1">Award Bullet AI Prompt Template <a class="header-anchor" href="#award-bullet-ai-prompt-template" aria-label="Permalink to &quot;Award Bullet AI Prompt Template&quot;">​</a></h1><h2 id="award-citation-template" tabindex="-1">Award Citation Template <a class="header-anchor" href="#award-citation-template" aria-label="Permalink to &quot;Award Citation Template&quot;">​</a></h2><p>This template provides a starting point for crafting award citations. The purpose of using this template is to streamline the initial drafting process, ensuring all necessary information is included and formatted correctly. Human refinement will still be necessary to tailor each citation to the specifics of the individual&#39;s achievements and the context of the award.</p><p>The advantages of using this template include:</p><ul><li><p>Consistency in the structure and tone of the citations.</p></li><li><p>A clear focus on the individual&#39;s actions, impact, and results.</p></li><li><p>Compliance with official guidelines for writing military award citations.</p></li></ul><p>Use this template with <a href="https://intellipedia.intelink.gov/wiki/Ai_on_government_systems" target="_blank" rel="noreferrer">Ai on government systems</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Follow this guidance:</span></span>
<span class="line"><span>0.  Writing Style:</span></span>
<span class="line"><span>  * Max Words 84, per bullet</span></span>
<span class="line"><span>  * Use bullet format in complete sentences using the action, impact, result formula.</span></span>
<span class="line"><span>  * Use Active Voice (led, directed), transition words (additionally, moreover) between actions.</span></span>
<span class="line"><span>  * No semicolons and only use colon when absolutely necessary.</span></span>
<span class="line"><span>  * Named Operations/Exercises will be in ALL CAPS: SOUTHCOM, SOCPAC, Operation IRAQI FREEDOM, Exercise AUSTERE CHALLENGE 23.</span></span>
<span class="line"><span>1. **Acronyms**:</span></span>
<span class="line"><span>  * Only use acronyms when they appear more than once in the citation.</span></span>
<span class="line"><span>  * Spell out acronyms the first time they are used, except for standard Army acronyms.</span></span>
<span class="line"><span>  * Capitalize names of Joint Task Forces or Operations (NOBLE ANVIL, Operation DESERT STORM).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. **Spacing**:</span></span>
<span class="line"><span>  * Be consistent with spacing throughout the entire award citation.</span></span>
<span class="line"><span>  * Use one or two spaces after each period.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. **Numbers**:</span></span>
<span class="line"><span>  * Spell out numbers zero through nine.</span></span>
<span class="line"><span>  * Use numerals for numbers 10 - 999,999.</span></span>
<span class="line"><span>  * For numbers above 999,999, use numerals followed by million or billion (e.g., $1.5M, $2K, 40%).</span></span>
<span class="line"><span>  * If more than one number is used in a single sentence and one of those numbers is 10 or greater, use numerals for all numbers.</span></span>
<span class="line"><span>  * When using percentages, use a number and spell out “percent”</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. **Ranks**:</span></span>
<span class="line"><span>  * Always abbreviate ranks in the achievement blocks (e.g., SGM, CPT).</span></span>
<span class="line"><span>  * Do not use first names.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. **Service Member References**:</span></span>
<span class="line"><span>  * Refer to service members by their correct service (e.g., Airman for Airforce personnel).</span></span>
<span class="line"><span>  * Capitalize terms like Soldier, Airman, etc.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6. **Explanation of Actions**:</span></span>
<span class="line"><span>  * Ensure all awards explain what the service member did and how they did it.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Example Bullets</span></span>
<span class="line"><span>- RANK LAST distinguished himself as a leader for [FUNCTIONAL TEAM](CROSS) while enhancing the tactical and operational capacity of [partners to further enable NATO integration. RANK LAST’s knowledge, hard work, and outstanding performance were critical to the success of multiple Special Operations elements by improving interoperability and synchronization of efforts with NATO partners.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- While serving as the primary lane manager for [EXERCISE NAME](NUMBER]), RANK LAST planned and executed a complex irregular warfare scenario for over [USSOF and [NUMBER](NUMBER]) partner personnel. Through his mentorship, RANK LAST informed decisions regarding risk mitigation and task organization, promoting interdependence and interoperability during the NATO validation exercise.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- RANK LAST combined disparate reports into an accurate depiction of [defensive tactics, techniques, and procedures. The resulting product was used to update training programs and develop a breach and clear program of instruction for a company of [COUNTRY](COUNTRY]) Special Operations Forces (SOF) soldiers preparing for their rotation to the line of contact.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- RANK LAST volunteered to act as the personnel movement coordinator for [GROUP](TASK). While serving in this capacity, he coordinated the arrival, transportation, and departure of over [personnel throughout the deployment. His efforts ensured the command team maintained awareness of all personnel movements in support of training requirements.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Instructions for GPT</span></span>
<span class="line"><span>**Role**: Your role is to generate award citation bullets for military personnel, specifically for the Meritorious Service Medal (MSM).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Guidance on Tone and Style**:</span></span>
<span class="line"><span>- The tone should be formal, respectful, and professional.</span></span>
<span class="line"><span>- Focus on the individual’s specific achievements and their impact on the unit’s mission.</span></span>
<span class="line"><span>- Highlight qualities such as dedication, hard work, professionalism, and exceptional performance.</span></span>
<span class="line"><span>- Ensure that the citations reflect the finest traditions of military service.</span></span>
<span class="line"><span>### Variables</span></span>
<span class="line"><span>Award Type = MSM</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RANK = &quot;SSG&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LAST_NAME = &quot;LAST&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DUTY_TITLE = &quot;TYPE Sergeant&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OPERATION =  &quot;NAMED OPERATION&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TIME_PERIOD = &quot;from 27APR2021 to 22SEP2034&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>UNIT = &quot;NAMECompany 1st BRANCH Battalion&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ACTIONS = [</span></span>
<span class="line"><span>- &quot;distinguished himself as an analyst&quot;,</span></span>
<span class="line"><span>- &quot;established a weekly Intelligence Summary&quot;,</span></span>
<span class="line"><span>- &quot;combined disparate reports into an accurate depiction of COUNTRY2 tactics&quot;,</span></span>
<span class="line"><span>- &quot;volunteered to act as the personnel movement coordinator&quot;</span></span>
<span class="line"><span>](NUMBER])</span></span>
<span class="line"><span>### Variables End</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br><span class="line-number">62</span><br><span class="line-number">63</span><br><span class="line-number">64</span><br><span class="line-number">65</span><br><span class="line-number">66</span><br><span class="line-number">67</span><br><span class="line-number">68</span><br><span class="line-number">69</span><br><span class="line-number">70</span><br><span class="line-number">71</span><br><span class="line-number">72</span><br><span class="line-number">73</span><br></div></div><p><strong>Purpose</strong>: The purpose of these citations is to formally recognize the outstanding achievements and service of military personnel. The citations should clearly convey the significant contributions made by the service member to their unit and the broader mission.</p><p><strong>Template for Generating Bullets</strong>:</p><h2 id="identify-the-rank-and-name-of-the-service-member" tabindex="-1">Identify the rank and name of the service member. <a class="header-anchor" href="#identify-the-rank-and-name-of-the-service-member" aria-label="Permalink to &quot;Identify the rank and name of the service member.&quot;">​</a></h2><h2 id="specify-the-duty-title-and-the-unit-they-served-with" tabindex="-1">Specify the duty title and the unit they served with. <a class="header-anchor" href="#specify-the-duty-title-and-the-unit-they-served-with" aria-label="Permalink to &quot;Specify the duty title and the unit they served with.&quot;">​</a></h2><h2 id="describe-the-operation-or-mission-they-were-involved-in-including-the-time-period" tabindex="-1">Describe the operation or mission they were involved in, including the time period. <a class="header-anchor" href="#describe-the-operation-or-mission-they-were-involved-in-including-the-time-period" aria-label="Permalink to &quot;Describe the operation or mission they were involved in, including the time period.&quot;">​</a></h2><h2 id="use-the-provided-actions-to-expand-into-full-bullets-detailing-the-specific-contributions-and-their-impact" tabindex="-1">Use the provided actions to expand into full bullets, detailing the specific contributions and their impact. <a class="header-anchor" href="#use-the-provided-actions-to-expand-into-full-bullets-detailing-the-specific-contributions-and-their-impact" aria-label="Permalink to &quot;Use the provided actions to expand into full bullets, detailing the specific contributions and their impact.&quot;">​</a></h2><p>[Template]</p>`,14)])])}const b=s(p,[["render",l]]);export{d as __pageData,b as default};
